const input = $('Find Prospects Webhook').first().json.body || {};
const geo = $input.first().json;
if (!Array.isArray(geo) || geo.length === 0) throw new Error('City/region not found by Nominatim');
const g = geo[0];
const bbox = g.boundingbox || [];
const south = Number(bbox[0]), north = Number(bbox[1]), west = Number(bbox[2]), east = Number(bbox[3]);
if (![south,north,west,east].every(Number.isFinite)) throw new Error('Invalid bounding box');

const niche = String(input.niche || '').toLowerCase();
const tagMap = [
  [/electric|electrician/, ['craft','electrician']],
  [/roof/, ['craft','roofer']],
  [/paint/, ['craft','painter']],
  [/plumb/, ['craft','plumber']],
  [/hvac|heating|air condition/, ['craft','hvac']],
  [/landscap|garden/, ['craft','landscaper']],
  [/clean/, ['craft','cleaner']],
  [/carpenter|wood/, ['craft','carpenter']],
  [/mason|masonry/, ['craft','stonemason']],
  [/construction|remodel|renovat|contractor/, ['office','construction_company']]
];
let pair = ['name', niche];
for (const [rx,p] of tagMap) if (rx.test(niche)) { pair=p; break; }

const [key,val] = pair;
const q = `[out:json][timeout:25];
(
  node["${key}"="${val}"](${south},${west},${north},${east});
  way["${key}"="${val}"](${south},${west},${north},${east});
  relation["${key}"="${val}"](${south},${west},${north},${east});
);
out center tags;`;

return [{json:{...input, overpassQuery:q, geocode:g.display_name, bbox:{south,west,north,east}}}];

const req = $('Build Overpass Query').first().json;
const data = $input.first().json;
const els = Array.isArray(data.elements) ? data.elements : [];
const limit = Math.min(Math.max(Number(req.limit || 10),1),25);
const seen = new Set();
const prospects = [];

function val(t,...keys){ for(const k of keys){ if(t?.[k]) return String(t[k]).trim(); } return ''; }
function normPhone(p){ return p.replace(/[^+\d]/g,''); }

for (const el of els) {
  const t = el.tags || {};
  const company = val(t,'name','brand','operator');
  if (!company) continue;
  const phone = val(t,'contact:phone','phone','contact:mobile','mobile');
  const email = val(t,'contact:email','email');
  const website = val(t,'contact:website','website','url');
  const street = [val(t,'addr:housenumber'),val(t,'addr:street')].filter(Boolean).join(' ');
  const locality = val(t,'addr:city','addr:town','addr:village','addr:suburb') || req.city || '';
  const address = [street,locality,req.country].filter(Boolean).join(', ');
  const key=(company+'|'+normPhone(phone)+'|'+email).toLowerCase();
  if (seen.has(key)) continue;
  seen.add(key);

  let score=55;
  let issue='Needs qualification';
  if (!website) {score+=25; issue='No website listed in OpenStreetMap';}
  if (phone) score+=10;
  if (email) score+=10;
  if (!phone && !email) score-=20;
  score=Math.max(0,Math.min(100,score));

  prospects.push({
    id:`osm-${el.type}-${el.id}`,
    company,
    niche:req.niche || '',
    country:req.country || '',
    city:req.city || locality,
    email,
    phone,
    website,
    whatsapp:'Unknown',
    status:'New',
    issue,
    score,
    source:'OpenStreetMap',
    address,
    osm_type:el.type,
    osm_id:el.id
  });
}
prospects.sort((a,b)=>b.score-a.score);
return [{json:{ok:true,query:{country:req.country,city:req.city,niche:req.niche},geocode:req.geocode,count:prospects.slice(0,limit).length,prospects:prospects.slice(0,limit)}}];
